private void injectElement(ReduceFnTester<Integer, ?, IntervalWindow> tester, int element) throws Exception {
    doNothing().when(mockTriggerStateMachine).onElement(anyElementContext());
    tester.injectElements(TimestampedValue.of(element, new Instant(element)));
}

private void injectElements(ReduceFnTester<Integer, ?, IntervalWindow> tester, Iterable<Integer> values) throws Exception {
