    FlinkMetricContainer flinkContainer = new FlinkMetricContainer(runtimeContext);
    MetricsContainerImpl step = flinkContainer.getMetricsContainer("step");
    MonitoringInfo intCounter = MonitoringInfo.newBuilder().setUrn(MonitoringInfoConstants.Urns.USER_COUNTER).putLabels(MonitoringInfoConstants.Labels.NAMESPACE, "ns1").putLabels(MonitoringInfoConstants.Labels.NAME, "int_counter").putLabels(MonitoringInfoConstants.Labels.PTRANSFORM, "step").setMetric(Metric.newBuilder().setCounterData(CounterData.newBuilder().setInt64Value(111))).build();
    MonitoringInfo doubleCounter = MonitoringInfo.newBuilder().setUrn(MonitoringInfoConstants.Urns.USER_COUNTER).putLabels(MonitoringInfoConstants.Labels.NAMESPACE, "ns2").putLabels(MonitoringInfoConstants.Labels.NAME, "double_counter").putLabels(MonitoringInfoConstants.Labels.PTRANSFORM, "step").setMetric(Metric.newBuilder().setCounterData(CounterData.newBuilder().setDoubleValue(222))).build();
    MonitoringInfo intDistribution = MonitoringInfo.newBuilder().setUrn(MonitoringInfoConstants.Urns.USER_COUNTER).putLabels(MonitoringInfoConstants.Labels.NAMESPACE, "ns3").putLabels(MonitoringInfoConstants.Labels.NAME, "int_distribution").putLabels(MonitoringInfoConstants.Labels.PTRANSFORM, "step").setMetric(Metric.newBuilder().setDistributionData(MetricsApi.DistributionData.newBuilder().setIntDistributionData(IntDistributionData.newBuilder().setSum(30).setCount(10).setMin(1).setMax(5)))).build();
    MonitoringInfo doubleDistribution = MonitoringInfo.newBuilder().setUrn(MonitoringInfoConstants.Urns.USER_COUNTER).putLabels(MonitoringInfoConstants.Labels.NAMESPACE, "ns4").putLabels(MonitoringInfoConstants.Labels.NAME, "double_distribution").putLabels(MonitoringInfoConstants.Labels.PTRANSFORM, "step").setMetric(Metric.newBuilder().setDistributionData(MetricsApi.DistributionData.newBuilder().setDoubleDistributionData(DoubleDistributionData.newBuilder().setSum(30).setCount(10).setMin(1).setMax(5)))).build();
    // Mock out the counter that Flink returns; the distribution gets created by
    // FlinkMetricContainer, not by Flink itself, so we verify it in a different way below
    SimpleCounter counter = new SimpleCounter();
    when(metricGroup.counter("ns1.int_counter")).thenReturn(counter);
    flinkContainer.updateMetrics("step", ImmutableList.of(intCounter, doubleCounter, intDistribution, doubleDistribution));
    // Flink's MetricGroup should only have asked for one counter (the integer-typed one) to be
    // created (the double-typed one is dropped currently)
    verify(metricGroup).counter(eq("ns1.int_counter"));
    // Verify that the counter injected into flink has the right value
    assertThat(counter.getCount(), is(111L));
    // Verify the counter in the java SDK MetricsContainer
    long count = ((CounterCell) step.tryGetCounter(MonitoringInfoMetricName.of(intCounter))).getCumulative();
    assertThat(count, is(111L));
    // The one Flink distribution that gets created is a FlinkDistributionGauge; here we verify its
    // initial (and in this test, final) value
    verify(metricGroup).gauge(eq("ns3.int_distribution"), argThat(new ArgumentMatcher<FlinkDistributionGauge>() {

        @Override
        public boolean matches(Object argument) {
            DistributionResult actual = ((FlinkDistributionGauge) argument).getValue();
            DistributionResult expected = DistributionResult.create(30, 10, 1, 5);
            return actual.equals(expected);
        }
    }));
    // Verify that the Java SDK MetricsContainer holds the same information
    DistributionData distributionData = ((DistributionCell) step.getDistribution(MonitoringInfoMetricName.of(intDistribution))).getCumulative();
    assertThat(distributionData, is(DistributionData.create(30, 10, 1, 5)));
}

