@Test
public void testLullReportsRightTrace() throws Exception {
    Thread mockThread = mock(Thread.class);
    DataflowExecutionState executionState = new DataflowExecutionState(NameContextsForTests.nameContextForTest(), "somestate", null, /* requestingStepName */
    null, /* inputIndex */
    null, /* metricsContainer */
    ScopedProfiler.INSTANCE.emptyScope()) {

        @Nullable
        @Override
        public CounterUpdate extractUpdate(boolean isFinalUpdate) {
            // not being used for extracting updates
            return null;
        }

        @Override
        public void takeSample(long millisSinceLastSample) {
            // Not being used for sampling
        }
    };
    when(mockThread.getStackTrace()).thenReturn(new StackTraceElement[] { new StackTraceElement("userpackage.SomeUserDoFn", "helperMethod", "SomeUserDoFn.java", 250), new StackTraceElement("userpackage.SomeUserDoFn", "process", "SomeUserDoFn.java", 450), new StackTraceElement(SimpleDoFnRunner.class.getName(), "processElement", "SimpleDoFnRunner.java", 500) });
    executionState.reportLull(mockThread, 6000);
    File[] files = logFolder.listFiles();
    assertThat(files, Matchers.arrayWithSize(1));
    String contents = Joiner.on("\n").join(Files.readAllLines(files[0].toPath()));
    assertThat(contents, Matchers.allOf(Matchers.containsString("Processing stuck in step " + NameContextsForTests.USER_NAME), Matchers.containsString(" without outputting or completing in state somestate"), Matchers.containsString("userpackage.SomeUserDoFn.helperMethod"), Matchers.not(Matchers.containsString(SimpleDoFnRunner.class.getName()))));
}

