public void testTransformReturnsValidCounterUpdateWhenValidUserMonitoringInfoReceived() {
    Map<String, DataflowStepContext> stepContextMapping = new HashMap<>();
    NameContext nc = NameContext.create("anyStageName", "anyOriginalName", "anySystemName", "anyUserName");
    DataflowStepContext dsc = mock(DataflowStepContext.class);
    when(dsc.getNameContext()).thenReturn(nc);
    stepContextMapping.put("anyValue", dsc);
    MonitoringInfo monitoringInfo = MonitoringInfo.newBuilder().setUrn("beam:metric:user_distribution").putLabels(MonitoringInfoConstants.Labels.NAME, "anyName").putLabels(MonitoringInfoConstants.Labels.NAMESPACE, "anyNamespace").putLabels(MonitoringInfoConstants.Labels.PTRANSFORM, "anyValue").build();
    UserDistributionMonitoringInfoToCounterUpdateTransformer testObject = new UserDistributionMonitoringInfoToCounterUpdateTransformer(mockSpecValidator, stepContextMapping);
    when(mockSpecValidator.validate(any())).thenReturn(Optional.empty());
    CounterUpdate result = testObject.transform(monitoringInfo);
    assertNotEquals(null, result);
    assertEquals("{cumulative=true, distribution={count={highBits=0, lowBits=0}, " + "max={highBits=0, lowBits=0}, min={highBits=0, lowBits=0}, " + "sum={highBits=0, lowBits=0}}, " + "structuredNameAndMetadata={metadata={kind=DISTRIBUTION}, " + "name={name=anyName, origin=USER, originNamespace=anyNamespace, " + "originalStepName=anyOriginalName}}}", result.toString());
}

