@Test
public void testBufferRateLimiting() throws Exception {
    AtomicInteger processedElements = new AtomicInteger();
    AtomicInteger currentTimeMillis = new AtomicInteger(10000);
    final int START_BUFFER_SIZE = 3;
    final int STEADY_BUFFER_SIZE = 10;
    final int FIRST_ELEMENT_DURATION = (int) RemoteGrpcPortWriteOperation.MAX_BUFFER_MILLIS / START_BUFFER_SIZE + 1;
    final int STEADY_ELEMENT_DURATION = (int) RemoteGrpcPortWriteOperation.MAX_BUFFER_MILLIS / STEADY_BUFFER_SIZE + 1;
    operation = new RemoteGrpcPortWriteOperation<>(beamFnDataService, TARGET, bundleIdSupplier, CODER, operationContext, () -> (long) currentTimeMillis.get());
    RecordingConsumer<WindowedValue<String>> recordingConsumer = new RecordingConsumer<>();
