    JobApi.PrepareJobRequest prepareRequest = JobApi.PrepareJobRequest.newBuilder().setJobName(TEST_JOB_NAME).setPipeline(RunnerApi.Pipeline.getDefaultInstance()).setPipelineOptions(Struct.getDefaultInstance()).build();
    RecordingObserver<JobApi.PrepareJobResponse> prepareRecorder = new RecordingObserver<>();
