@Test
public void testCreatingAndProcessingBeamFnDataReadRunner() throws Exception {
    String bundleId = "57";
    List<WindowedValue<String>> outputValues = new ArrayList<>();
    MetricsContainerStepMap metricsContainerRegistry = new MetricsContainerStepMap();
    PCollectionConsumerRegistry consumers = new PCollectionConsumerRegistry(metricsContainerRegistry, mock(ExecutionStateTracker.class));
    String localOutputId = "outputPC";
    String pTransformId = "pTransformId";
    consumers.register(localOutputId, pTransformId, (FnDataReceiver) (FnDataReceiver<WindowedValue<String>>) outputValues::add);
    PTransformFunctionRegistry startFunctionRegistry = new PTransformFunctionRegistry(mock(MetricsContainerStepMap.class), mock(ExecutionStateTracker.class), "start");
    PTransformFunctionRegistry finishFunctionRegistry = new PTransformFunctionRegistry(mock(MetricsContainerStepMap.class), mock(ExecutionStateTracker.class), "finish");
    RunnerApi.PTransform pTransform = RemoteGrpcPortRead.readFromPort(PORT_SPEC, localOutputId).toPTransform();
    new BeamFnDataReadRunner.Factory<String>().createRunnerForPTransform(PipelineOptionsFactory.create(), mockBeamFnDataClient, null, /* beamFnStateClient */
    pTransformId, pTransform, Suppliers.ofInstance(bundleId)::get, ImmutableMap.of(localOutputId, RunnerApi.PCollection.newBuilder().setCoderId(ELEMENT_CODER_SPEC_ID).build()), COMPONENTS.getCodersMap(), COMPONENTS.getWindowingStrategiesMap(), consumers, startFunctionRegistry, finishFunctionRegistry, null);
    verifyZeroInteractions(mockBeamFnDataClient);
    InboundDataClient completionFuture = CompletableFutureInboundDataClient.create();
    when(mockBeamFnDataClient.receive(any(), any(), any(), any())).thenReturn(completionFuture);
    Iterables.getOnlyElement(startFunctionRegistry.getFunctions()).run();
    verify(mockBeamFnDataClient).receive(eq(PORT_SPEC.getApiServiceDescriptor()), eq(LogicalEndpoint.of(bundleId, BeamFnApi.Target.newBuilder().setPrimitiveTransformReference("pTransformId").setName(Iterables.getOnlyElement(pTransform.getOutputsMap().keySet())).build())), eq(CODER), consumerCaptor.capture());
    consumerCaptor.getValue().accept(valueInGlobalWindow("TestValue"));
    assertThat(outputValues, contains(valueInGlobalWindow("TestValue")));
    outputValues.clear();
    assertThat(consumers.keySet(), containsInAnyOrder(localOutputId));
    completionFuture.complete();
    Iterables.getOnlyElement(finishFunctionRegistry.getFunctions()).run();
    verifyNoMoreInteractions(mockBeamFnDataClient);
}

