@Test
public void shouldReturnAllRecords() throws TransientKinesisException, KinesisShardClosedException {
    when(firstIterator.readNextBatch()).thenReturn(Collections.emptyList()).thenReturn(ImmutableList.of(a, b)).thenReturn(Collections.emptyList());
    when(secondIterator.readNextBatch()).thenReturn(singletonList(c)).thenReturn(singletonList(d)).thenReturn(Collections.emptyList());
    shardReadersPool.start();
    List<KinesisRecord> fetchedRecords = new ArrayList<>();
    while (fetchedRecords.size() < 4) {
        CustomOptional<KinesisRecord> nextRecord = shardReadersPool.nextRecord();
        if (nextRecord.isPresent()) {
            fetchedRecords.add(nextRecord.get());
        }
    }
